 import { formatCents } from "./format.js";

+// Sum of the prices of all items of an order, in cents.
+export function sumPrices(items) {
+  let total = 0;
+  for (let i = 0; i <= items.length; i++) {
+    total += items[i].price;
+  }
+  return total;
+}
+
 export function formatTotal(order) {
   return formatCents(order.total);
 }
